export const RippleButton = styled(ButtonBase)({
    position: 'relative',
    overflow: 'hidden',
    //borderRadius: '50%',
    userSelect: 'none',
    cursor: 'pointer',
    transition: 'background-color 0.3s',
  
    '&:before': {
      content: '""',
      position: 'absolute',
      width: '300%',
      height: '300%',
      //borderRadius: '50%',
      backgroundColor: 'rgba(255, 255, 255, 0.3)',
      transform: 'scale(0)',
      transition: 'transform 0.3s, opacity 0.3s',
      pointerEvents: 'none',
    },
  
    '&:hover:before': {
    //   transform: 'scale(1)',
    //   opacity: 0,
    },
  });
  
  export const RippleEffectButton = ({ onClick, children } : any) => {
    return (
      <RippleButton onClick={onClick}>
        {children}
      </RippleButton>
    );
  };


  export const ButtonRoundedTransition = ({ onClick, color1, color2, outline, width, height }:any) => {

    const lineWidth : number = 2
    const borderRadius = 50
    const flip = outline

    const StackDynamic = ({ children } : any ) => {

        const children2: any[] = getChildren( children );
        
        return (
            <>
                <StackII>
                    { !flip ? <>{ children2.length > 0 ? children2[0] : undefined }</> : <>{ children2.length > 1 ? children2[1] : undefined }</> }
                    { !flip ? <>{ children2.length > 1 ? children2[1] : undefined }</> : <>{ children2.length > 0 ? children2[0] : undefined }</> }
               </StackII>
            </>
        )
    }



    return (
     
        
            <div style={{
                 width : width ? width : 300, 
                 height : height ? height : 50, 
                 borderRadius, 
                 overflow : 'hidden'
                
            }}>
                <RippleEffectButton onClick={onClick}>
                
                    <StackDynamic>
                        <div {...css({ 
                            width : width ? width : 300, 
                            height : height ? height : 50, 
                            borderRadius, 
                            background: `linear-gradient(45deg, ${color1 ? color1 : 'red'}, ${color2 ? color2 : 'blues' })`,
                            color : 'white',
                            opacity : flip ? 0 : 1,
                            transition : '300ms',
                            [onHover] : {
                                opacity : flip ? 1 : 0
                            }
                        
                            
            
                            })}>
                                <XY>
                                    Here is the text
                                </XY>
                            
                        </div>
                        <div {...css({ 
                            width : width ? width : 300, 
                            height : height ? height : 50, 
                            borderRadius, 
                            background: `linear-gradient(45deg, ${color1 ? color1 : 'red'}, ${color2 ? color2 : 'blues' })`,
                            transition : '300ms',
                            opacity : flip ? 1 : 0,
                            [onHover] : {
                                opacity : flip ? 0 : 1
                            }
                        
                        
            
                            })}>    
                                <XY>
                                    <div style={{
                                        width : (width ? width  : 300) - lineWidth*2,
                                        height : (height ? height : 50) - lineWidth*2, 


                                        borderRadius, 
                                        backgroundColor : 'white'
                                    }}>
                                        <XY>
                                            Here is the text
                                        </XY>
                                </div>
                                </XY>
                                
                        </div>
                    </StackDynamic>
                </RippleEffectButton>
            </div>
   
      
    );
  };


  
