export const IconBorderAndBackground = ( props : {
    align ?: any, 
    lineWidth :  number,
    innerRadius : number | string, 
    outerRadius :  number | string,
    width :  number, 
    height :  number, 
    children ?: any,
    color ?: string, 
    colorHover?: string, 
    backgroundColor ?: string, 
    backgroundColorHover ?: string, 
    gradient ?: any, 
    link ?: { href ?: any, value ?: any, icon ?: any, iconProps ?: any  }
    iconOffset ?: {
        x ?: number, 
        y ?: number, 
    }
  
}) => {

    const color : any = props?.color ?? 'black'
    const colorHover : any = props?.colorHover ?? color

    const backgroundColor : any = props?.backgroundColor ?? 'black'
    const backgroundColorHover : any = props?.backgroundColorHover ?? backgroundColor
    const Icon = props?.link?.icon ?? <></>
    const iconProps : any = props?.link?.iconProps ?? {}

    return(
        <a href={props?.link?.href ?? undefined} {...css({
            ...getFontPoppins(),
            color : iconProps?.color,
            transition : "200ms", 
            [':link'] : { color : iconProps?.color, textDecoration : 'none'},
            [':visited'] : { color : iconProps?.color, textDecoration : 'none' },
            [':hover'] : { color : iconProps?.colorHover, textDecoration : 'none' }
        })}>
       
            <div style={{ marginTop : -5, marginLeft : 8, width : props.width, height : props.height, ...props?.gradient, borderRadius : props.outerRadius, marginBottom : 5 }}>
            
                    <div {...css({ 
                        marginLeft : props.lineWidth/2, 
                        transform : `translate(0,${props.lineWidth/2}px)`,  
                        width : props.width - props.lineWidth, 
                        height : props.height - props.lineWidth, 
                        backgroundColor,  
                        color,
                        borderRadius : props.innerRadius,
                        transition : '200ms',
                        ...appendIf( !!(props?.backgroundColorHover || props?.colorHover ),{
                            [onHover] : {
                                backgroundColor :  backgroundColorHover,
                                color : colorHover
                            }
                        } )
                        
                        
                    })}>
                  
                        <XY align={ props?.align ?? 'center'}>
                            <div style={{ transform : 'translate(-4.5px,0)'}}>
                                
                                    <div {...css({ marginLeft : 10 })}>
                                        <X>
                                            <Icon style={ !props?.iconOffset ? {} : { 
                                                transform : `translate( ${props.iconOffset?.x ?? 0 }px,${props.iconOffset?.y ?? 0 }px)`
                                            }} size={iconProps?.size}/>
                                            {props.children}
                                        </X>
                                    </div>
                                </div>
                        </XY>
                    </div>
            </div>
        </a>
    )     
}

