export const ContainerThirdsStackOnBreak = ({ breakpoint, children } : any ) => {
    const childComponents : any[] = getChildren(children)

    return (
        <div>
            <Hide on={ breakpoint ?? 960 }>
            <ContainerThirdsV>       
                { childComponents.length > 0 && <>{childComponents[0]}</>} 
                { childComponents.length > 1 && <>{childComponents[1]}</>} 
                { childComponents.length > 2 && <>{childComponents[2]}</>} 
            </ContainerThirdsV>
            </Hide>
            <Hide b4={ breakpoint ?? 960 }>
                <Y>
                    { childComponents.length > 0 && <>{childComponents[0]}</>} 
                    { childComponents.length > 1 && <>{childComponents[1]}</>} 
                    { childComponents.length > 2 && <>{childComponents[2]}</>} 
                </Y>
            </Hide>
        </div>
    )
}




export const ContainerHalvesStackOnBreak = ({ breakpoint, children, percent, debug, gap } : any ) => {
    const childComponents : any[] = getChildren(children)

    const defaultBreak : number = 960
    return (
        <>
            <Hide on={  breakpoint ?? defaultBreak }>
                <ContainerSplitPercent show={ debug } percent={ percent ?? 50} gap={ gap ?? 0}>
                    {childComponents.length > 0 && childComponents[0] }
                    {childComponents.length > 1 && childComponents[1] }
                </ContainerSplitPercent>
            </Hide>
            <Hide b4={  breakpoint ?? defaultBreak }>
                <Y>
                    {childComponents.length > 0 && childComponents[0] }
                    {childComponents.length > 1 && childComponents[1] }

                </Y> 
            </Hide>

        </>
    )
}


export const ContainerPartsStackOnBreak = ({ breakpoint, children, width, right, debug, gap } : any ) => {
    const childComponents : any[] = getChildren(children)

    const defaultBreak : number = 960

    const DynamicElement : any = right ? ContainerSplitR : ContainerSplitL


    const dynamicProps : any = {
        [`${ right ? 'widthRight' : 'widthLeft' }`] : width,
        show : debug, 
        gap : gap ?? 0
    }

    return (
        <>
            <Hide on={  breakpoint ?? defaultBreak }>
                <DynamicElement {...dynamicProps}>
                    {childComponents.length > 0 && childComponents[0] }
                    {childComponents.length > 1 && childComponents[1] }
                </DynamicElement>
            </Hide>
            <Hide b4={  breakpoint ?? defaultBreak }>
                <Y>
                    {childComponents.length > 0 && childComponents[0] }
                    {childComponents.length > 1 && childComponents[1] }

                </Y> 
            </Hide>

        </>
    )
}


