export const ContainerImageGradient = ( props : { 
    style ?: any, 
    opacity ?: number, 
    opacity1 ?: number, 
    opacity2 ?: number, 
    children ?: any, 
    image ?: any, 
    rgbFragment1 ?: string, 
    rgbFragment2 ?: string,
    borderRadius ?: string | number  
}) => {    

    const opacity : number = props?.opacity ?? 0.6
    const opacity1 : number | undefined = props?.opacity1 ?? undefined
    const opacity2 : number | undefined = props?.opacity2 ?? undefined

    const rgbFragment1 : string = props?.rgbFragment1 ?? '0,0,0'
    const rgbFragment2 : string = props?.rgbFragment2 ?? '0,0,0'

    return (
        
            <div {...css({ 
                width : '100%', 
                backgroundPosition: 'center center', 
                backgroundImage: `url(${ props?.image ?? getImagePlaceholder() })`, 
                backgroundSize: 'cover',
                backgroundRepeat: 'no-repeat',
                overflow : 'hidden',
                borderRadius : props?.borderRadius ?? '', 
                ...props.style,
            })}>
                <ContainerGradient color1={`rgba(${rgbFragment1},${ opacity1 ?? opacity})`} color2={`rgba(${rgbFragment2},${opacity2 ?? opacity})`}>
                    
                    { props?.children }
                </ContainerGradient>
            </div>
    
    )
}











