export const CustomForm = ( props : {
    buttonColor ?: string, 
    buttonColorHover  ?: string, 
    spinnerColor  ?: string, 
 } ) => {


    const [isSubmitting, setIsSubmitting] = useState(false); // Track submission status
    const [isResponse, setIsResponse] = useState(false); // Track submission status

    const fieldHeight = "40px"; // Variable for height of fields
    const yOffset = -9; // Variable to adjust the vertical position of caret/placeholder text
    const gutter = "10px"; // Vertical space between fields
    const hoverColor =  props.buttonColorHover ?? "#0057D8"; // Hover color for the submit button
    const buttonColor =  props.buttonColor ?? 'black'
    const borderColor = props.buttonColorHover ?? "#0057D8"
    const spinnerColor : string = props.spinnerColor ?? "white"
  
    const [formData, setFormData] = React.useState({
      name: "",
      email: "",
      hoursRequested: "Hours Requested",
      dateOfBooking: null,
      numberOfPassengers: "Number of Passengers",
      phone: "",
      notes: "",
    });
  
    const handleChange = (field: string, value: string | Date | null) => {
      setFormData((prevData) => ({ ...prevData, [field]: value }));
    };

    const getValueOrFallbackHelper = ( value : any, fallback ?: string ) => {
        if( !value ) return fallback ?? 'EMPTY';//if( value.trim().length <= 0 ) return fallback ?? 'EMPTY';
        return String(value);
    }

    const handleSubmit = async () => {
        //alert("Submitting:" + isSubmitting); // Debug the state
        setIsSubmitting(true); // Disable the button and show the spinner
        try {
            submitTestForm({
                name: getValueOrFallbackHelper( formData.name),
                email: getValueOrFallbackHelper( formData.email, 'test@gmail.com' ),
                hours: getValueOrFallbackHelper( formData.hoursRequested),
                date: getValueOrFallbackHelper( formData.dateOfBooking),
                passengers: getValueOrFallbackHelper( formData.numberOfPassengers),
                phone: getValueOrFallbackHelper( formData.phone),
                notes: getValueOrFallbackHelper( formData.notes),
                onResponse : ( response ?: any ) => { 
                    console.log( response ); 
                    setIsSubmitting( false ); 
                    setIsResponse( true );
                }
            });
          } catch (error) {
            console.error("Submission failed:", error);
          } 
    };



    const theme = createTheme({
        components: {
            MuiTextField: {
                styleOverrides: {
                    root: {
                        "& .MuiOutlinedInput-root": {
                            "&:hover .MuiOutlinedInput-notchedOutline": {
                                borderColor: "transparent", // Remove hover border
                            },
                            "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
                                borderColor: "transparent", // Remove focus border
                            },
                        },
                    },
                },
            },
            MuiAutocomplete: {
                styleOverrides: {
                    root: {
                        "&:hover .MuiOutlinedInput-notchedOutline": {
                            borderColor: "transparent", // Remove hover border for Autocomplete
                        },
                        "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
                            borderColor: "transparent", // Remove focus border for Autocomplete
                        },
                    },
                },
            },
        },
    });
  
    const textFieldStyles = {
      backgroundColor: "#fff",
      border: `1px solid ${borderColor}`, // Yellow border
      borderRadius: "6px",
      width: "100%", // Ensure the width is 100% for responsiveness
      height: fieldHeight, // Apply height from variable
      transition: "background-color 0.3s ease", // Smooth background change on focus
      "& .MuiOutlinedInput-root": {
        boxSizing: "border-box",
        "& .MuiOutlinedInput-notchedOutline": {
          borderColor: "transparent", // Remove any internal greyish border
        },
        "&:focus-visible": {
          outline: "none", // Disable default focus outline
        },
      },
      // Adjust the placeholder and caret vertical position using transform
      "& .MuiInputBase-input": {
        transform: `translateY(${yOffset}px)`, // Adjust caret/placeholder position
      },
    };
  
    const multilineStyles = {
      backgroundColor: "#fff",
      border: `1px solid ${borderColor}`, // Yellow border
      borderRadius: "6px",
      width: "100%", // Ensure the width is 100% for responsiveness
      transition: "background-color 0.3s ease", // Smooth background change on focus
      "& .MuiOutlinedInput-root": {
        alignItems: "flex-start",
        boxSizing: "border-box",
        "& .MuiOutlinedInput-notchedOutline": {
          borderColor: "transparent", // Remove any internal greyish border
        },
      },
      "& .MuiInputBase-input": {
        textAlign: "left",
        resize: "none",
        overflowWrap: "break-word",
        lineHeight: "normal", // Default line height for multiline
        paddingTop: `${yOffset}px`, // Adjust padding to control vertical position for multiline
      },
      "&.Mui-focused": {
        backgroundColor: "rgba(0, 0, 0, 0.01)", // Background change on focus
      },
    };
  
    return (
        <div style={{ paddingRight: 4 }}>
            <StackII>
                <div style={{ 
                    transition : "400ms",
                    transitionDelay : "200ms",
                    opacity : isResponse ? 1 : 0,
                    width : 'calc(100% + 6px)', 
                    height : 'calc(100% + 6px)', 
                    backgroundColor : THEME.color.primary, 
                    marginLeft : -3, 
                    marginTop : -3 
                }}>
                    <XY>
                        <TitleX id="TitleIII" color="white"> Thank you we will contact you shortly</TitleX>
                    </XY>
                </div>
                <div style={{ 
                    opacity : isResponse ? 0 : 1,
                    transition : "400ms",
                   
                }}>
                    <ThemeProvider theme={theme}>
                        <LocalizationProvider dateAdapter={AdapterDateFns}>
                            <Box
                            sx={{
                                maxWidth: "800px", // Limit the max width
                                width: "100%", // Allow the form to take full width within the parent
                                mx: "auto", // Center the form horizontally
                                p: 0,
                                display: "flex",
                                flexDirection: "column",
                                gap: gutter, // Apply the gutter variable for vertical spacing between fields
                            }}
                            >
                            {/* <Typography variant="h5" textAlign="center" mb={2}>
                                Booking Form
                            </Typography> */}
                            {/* Name */}
                            <TextField
                                variant="outlined"
                                placeholder="Name"
                                value={formData.name}
                                onChange={(e) => handleChange("name", e.target.value)}
                                sx={{
                                ...textFieldStyles,
                                "&.Mui-focused": {
                                    backgroundColor: "rgba(0, 0, 0, 0.01)", // Background change on focus
                                },
                                }}
                            />
                            {/* Email */}
                            <TextField
                                variant="outlined"
                                placeholder="Email"
                                value={formData.email}
                                onChange={(e) => handleChange("email", e.target.value)}
                                sx={{
                                ...textFieldStyles,
                                "&.Mui-focused": {
                                    backgroundColor: "rgba(0, 0, 0, 0.01)", // Background change on focus
                                },
                                }}
                            />
                            {/* Hours Requested */}
                            <TextField
                                select
                                value={formData.hoursRequested}
                                onChange={(e) => handleChange("hoursRequested", e.target.value)}
                                sx={{
                                    ...textFieldStyles,
                                    "& .MuiSelect-select": {
                                    textAlign: "left", // Left-align dropdown content
                                    },
                                    "&.Mui-focused": {
                                    backgroundColor: "rgba(0, 0, 0, 0.01)", // Background change on focus
                                    },
                                    "& .MuiSelect-icon": {
                                    transform: `translateY(${yOffset}px)`, // Move chevron icon with offset
                                    },
                                }}
                                >
                                <MenuItem value="Hours Requested" disabled>
                                    Hours Requested
                                </MenuItem>
                                {[...Array(7).keys()].map((hour) => (
                                    <MenuItem key={hour + 1} value={`${hour + 1} Hour${hour > 0 ? "s" : ""}`}>
                                    {hour + 1} Hour{hour > 0 ? "s" : ""}
                                    </MenuItem>
                                ))}
                                <MenuItem value="Other">Other</MenuItem>
                                </TextField>

                                <DatePicker
                                value={formData.dateOfBooking}
                                onChange={(newValue) => handleChange("dateOfBooking", newValue)}
                                slotProps={{
                                    textField: {
                                    sx: {
                                        ...textFieldStyles,
                                        "&.Mui-focused": {
                                        backgroundColor: "rgba(0, 0, 0, 0.01)", // Background change on focus
                                        },
                                    },
                                    },
                                    inputAdornment: {
                                    sx: {
                                        transform: `translateY(${yOffset}px)`, // Move calendar icon with offset
                                    },
                                    },
                                }}
                                />
                            {/* Number of Passengers */}
                            <TextField
                                select
                                value={formData.numberOfPassengers}
                                onChange={(e) => handleChange("numberOfPassengers", e.target.value)}
                                sx={{
                                    ...textFieldStyles,
                                    "& .MuiSelect-select": {
                                    textAlign: "left", // Left-align dropdown content
                                    },
                                    "&.Mui-focused": {
                                    backgroundColor: "rgba(0, 0, 0, 0.01)", // Background change on focus
                                    },
                                    "& .MuiSelect-icon": {
                                    transform: `translateY(${yOffset}px)`, // Move chevron icon with offset
                                    },
                                }}
                                >
                                <MenuItem value="Number of Passengers" disabled>
                                    Number of Passengers
                                </MenuItem>
                                {["1-6", "7-8", "9-10", "11-14", "15-20", "21-26", "27-30", "Other"].map(
                                    (option) => (
                                    <MenuItem key={option} value={option}>
                                        {option}
                                    </MenuItem>
                                    )
                                )}
                                </TextField>
                            {/* Phone */}
                            <TextField
                                variant="outlined"
                                placeholder="Phone"
                                value={formData.phone}
                                onChange={(e) => handleChange("phone", e.target.value)}
                                sx={{
                                ...textFieldStyles,
                                "&.Mui-focused": {
                                    backgroundColor: "rgba(0, 0, 0, 0.01)", // Background change on focus
                                },
                                }}
                            />
                            {/* Event or Occasion */}
                            <Box
                                sx={{
                                position: "relative",
                                "& textarea": {
                                    overflow: "hidden", // Hide overflow as the textarea expands
                                },
                                }}
                            >
                                <TextField
                                    variant="outlined"
                                    placeholder="Event or Occasion"
                                    multiline
                                    minRows={4}
                                    value={formData.notes}
                                    onChange={(e) => handleChange("notes", e.target.value)} // Update 'occasion' to 'notes'
                                    sx={{
                                        ...multilineStyles,
                                        "&.Mui-focused": {
                                        backgroundColor: "rgba(0, 0, 0, 0.01)", // Background change on focus
                                        },
                                    }}
                                />
                            </Box>
                            {/* Send Button */}
                            <Button
                                onClick={handleSubmit}
                                variant="contained"
                                color="primary"
                                sx={{
                                    backgroundColor: buttonColor ?? "#000",
                                    color: "#fff",
                                    height: fieldHeight,
                                    borderRadius: "6px",
                                    mt: 0, // Spacing from the previous field
                                    display: "flex",
                                    justifyContent: "center",
                                    alignItems: "center",
                                    "&:hover": {
                                    backgroundColor: hoverColor, // Hover color for the button
                                    },
                                    width: "100%", // Ensure the button fills the container
                                    position: "relative", // Ensure spinner can be absolutely positioned if needed
                                    pointerEvents: isSubmitting ? "none" : "auto", // Disable button interaction during submit
                                }}
                                disabled={isSubmitting} // Disable button while submitting
                                >
                                {isSubmitting ? (
                                    <CircularProgress size={24} sx={{ position: "absolute", color :  spinnerColor }} />
                                ) : (
                                    'Send'
                                )}
                            </Button>
                            </Box>
                        </LocalizationProvider>
                    </ThemeProvider>
                </div>
            </StackII>
        </div>
    );
};

