import { css } from "glamor"
import React from "react"
import { on } from "./Hide"

const VERSION : number = 3

export default ( props : { onClick ?: () => void, height ?: number | string, align ?: 'top'|'middle'|'bottom', children ?: any, bgc ?: string, style ?: any  }) => {
    return <GridRow {...props}/>
}


const GridRow = ( props : { onClick ?: () => void, height ?: number | string, align ?: 'top'|'middle'|'bottom', children ?: any, bgc ?: string, style ?: any  }) => {
    return <div onClick={props.onClick} {...css({ backgroundColor : '', display : 'inline-block', width : 'auto', ...props.style})}>
        <div style={{ display : 'table-cell', height : props.height ? props.height : 30, verticalAlign : props.align ? props.align : 'middle'}}>
            {props.children}
        </div>
    </div>
}

export const GridRowRsp = ( props : { 
    onClick ?: () => void, 
    height ?: number | string, 
    heightBreakpoint ?: number | string, 
    align ?: 'top'|'middle'|'bottom', 
    children ?: any, 
    bgc ?: string, 
    style ?: any,
    breakpoint ?: number  
}) => {


    if( !!props.breakpoint && !!props.heightBreakpoint ) return (
        <div onClick={props.onClick} {...css({ display : 'inline-block', width : 'auto', backgroundColor : props.bgc ? props.bgc : '', ...props.style})}>
            <div {...css({ 
                    display : 'table-cell', 
                    height : props.height ? props.height : 30, 
                    verticalAlign : props.align ? props.align : 'middle',
                    [on(props.breakpoint)] : {
                        height : props.heightBreakpoint ? props.heightBreakpoint : 30,
                    }
            })}>
                {props.children}
            </div>
        </div>
    )
    else return <GridRow {...props}/>
}