import React from "react";


export default ( props : {
    children ?: any,
    angle ?: number,
    color1 ?: string, 
    color2 ?: string, 
}) => {

    const VERSION : number = 2.0
    let direction : any = props?.angle ? `${props?.angle}deg` : '180deg'
    let c1 : string = props?.color1 ? props.color1 : 'whitesmoke'
    let c2 : string = props?.color2 ? props.color2 : 'transparent'

    return (
        <div style={{ width : '100%', height : '100%', background :`linear-gradient(${direction}, ${c1} 0%, ${c2} 100%)`}}>
            {props.children}        
        </div>
    )
}