import { useEffect, useRef, useState } from "react";
import PageAndPopupGalleryAndPopupLeadV2 from "../../../locust/composables/PageAndPopupGalleryAndPopupLeadV2";
import React from "react";
import { content } from "../landing-content";
import SpacerV from "../../../locust/composables/SpacerV";
import { motion } from "framer-motion";
import { Center } from "../../../locust/composables/Center";
import GridRow from "../../../locust/composables/GridRow";
import ImportFjallaOne from "../../../assets/fonts/FjallaOne/ImportFjallaOne";
import FooterV3 from "./FooterV3";
import ThreeSectionFixedHeader, { HeaderSettings } from "./ThreeSectionFixedHeader";
import FooterV4 from "./FooterV4";
import ImportMontserratAlt from "../../../assets/fonts/FontMontserratAlt/ImportMontserratAlt";
import ImportPoppins from "../../../assets/fonts/Poppins/ImportPoppins";

export default ( props : { 
    color1 ?: any, 
    color2 ?: any, 
    children ?: any, 
    footer ?: {
        hide ?: boolean, 
        override ?: any, 
        sx ?: any
    },
    header ?: {
        debug ?: boolean,  // colorize sections
        hide ?: boolean,  // hide is to hide the component itself
        menu ?: any, 
        toggle ?: boolean, 
        override ?: any,
        settings ?: HeaderSettings
    },
    popup ?: {
        gallery ?: {
            toggle ?: boolean,
            images ?: any,
            title ?: any,
            onClose ?: () => void,
            imageIndex ?: number
        }
        lead ?:{
            toggle ?: boolean,
            images ?: any,
            title ?: any,
            onClose ?: () => void,
        }
    }
}) => {

 
    

    const [ galleryPopup, setGalleryPopup ] = useState( props?.popup?.gallery?.toggle )  
    useEffect(()=>{
        if( props?.popup?.gallery?.toggle !== undefined )
            setGalleryPopup( props.popup.gallery.toggle )
    },[ props?.popup?.gallery?.toggle ])


    const [ leadPopup, setLeadPopup ] = useState( props?.popup?.lead?.toggle )  
    useEffect(()=>{
        if( props?.popup?.lead?.toggle !== undefined )
        setLeadPopup( props.popup.lead.toggle )
    },[ props?.popup?.lead?.toggle ])


    const [ viewerIndex, setViewIndex ] = useState(-1); 
    const openGallery = () => setGalleryPopup( true )
    const openLead = () => setLeadPopup( true )
    const openImage = ( index : number ) => setViewIndex( index )

    const prefix : string = 'test'

    return (
        <>
            <ImportFjallaOne/>
            <ImportMontserratAlt/>
            <ImportPoppins/>

            <PageAndPopupGalleryAndPopupLeadV2
                version={ 2 }
                title={content.page.title}
                description={content.page.description}
                content={ content }
                popupGallery={{
                    toggle : galleryPopup,
                    images : content.gallery,
                    //title : <>Una Tile</>,
                    onClose : () => props?.popup?.gallery?.onClose 
                        ? props.popup.gallery.onClose() 
                        : setGalleryPopup(false),
                    imageIndex : viewerIndex
                }}
                popupLead={{
                    //title : <>Una Tile</>,
                    email : content.socials.email,
                    //title : content.socials.title,
                    toggle : leadPopup,
                    onClose : () => props?.popup?.lead?.onClose 
                    ? props.popup.lead.onClose() 
                    :setLeadPopup(false),
                }}
            >          
                
                {!props?.header?.hide ? <>
                    { 
                        props?.header?.override 
                            ? <>{ props.header.override }</> 
                            : <ThreeSectionFixedHeader 
                                    toggle={ props?.header?.toggle ?? false }
                                    debug={ props?.header?.debug ?? false }
                                    hide={ props?.header?.hide ?? false  }
                                    menu={ props?.header?.menu }
                                    settings={props?.header?.settings ?? undefined } 
                            >
                                <div style={{ marginTop : -5}}>
                                    { props.children }
                                </div>
                            </ThreeSectionFixedHeader>
                        }
                </> : 
                    <>{ props.children }</>
                }
                
                <FooterV4 
                    policy={{ privacy : false, tos : false, sitemap : false }}
                    color1={ props.color1} 
                    color2={ props.color2 } 
                    sx={props?.footer?.sx ?? undefined }
                />
                

            </PageAndPopupGalleryAndPopupLeadV2>
            
            <LoadingIntro hide={content?.sections?.intro?.hide ? true : false }/>
                
        </>
    )
}





const LoadingIntro = ( props : { hide ?: boolean }) => {

    const initialProps : any = {
        initial : { opacity : 0 }, animate : { opacity : 1}, transition : { delay : 0.5, duration : 0.5 }
    }
    
    if( props.hide ) return <></>
    return (<>

        <motion.div {...{
            initial : { display : 'relative' }, 
            animate : { display : 'none' }, 
            transition : { delay : 4.5, duration : 0.1 }
        }}>
            <motion.div {...{
                initial : { opacity : 1, position : 'fixed', top : 0, left : 0, width : '100vw', height : '100vh' }, 
                animate : { opacity : 0, height : 0 }, 
                transition : { delay : 3.5, duration : 1.0 }
            }}>
                <div style={{ backgroundColor : 'white', width : '100vw', height : '100vh'}}>
                    <motion.div {...initialProps}>
                        <Center>
                            <GridRow height="100vh">
                                <motion.div {...{
                                        initial : { transform : `rotate(0deg)` }, 
                                        animate : { transform : `rotate(360deg)` }, 
                                        transition : { delay : 1.5, duration : 0.4 }
                                    }}>
                                    
                                    <motion.div {...{
                                        initial : { marginTop : `-300px` }, 
                                        animate : { marginTop : `50px` }, 
                                        transition : { delay : 1, duration : 0.5 }
                                    }}>
                                        <img src={content.assets.logo.basic.img}/>
                                    </motion.div>
                                    <motion.div {...{
                                        initial : { marginTop : `2000px` }, 
                                        animate : { marginTop : `-50px` }, 
                                        transition : { delay : 1, duration : 0.5 }
                                    }}>
                                        <img src={content.assets.logo.basic.img}/>
                                    </motion.div> 
                                </motion.div>
                                <SpacerV h={10}/>
                                <motion.div {...{
                                    initial : { opacity : 0 }, 
                                    animate : { opacity : 1 }, 
                                    transition : { delay : 2.5, duration : 0.5 }
                                }}>
                                    <img src={content.assets.logo.basic.img}/>
                                </motion.div>
                            </GridRow>
                        </Center>
                    </motion.div>
                </div>
            </motion.div>
        </motion.div>
        
    </>)
}


