const MenuItemHoverDropdown = ( props : { onClick : () => void, color ?: any, colorHover ?: any, children ?: any,  href ?: string, items ?: { value : string, href ?: string }[] }) => {

    const menuItemHeight : number = 50

    const color : any = {
        fontWeight : 500, 
        transition : "300ms",
        ...getFontPoppins(),
        color : props?.color ?? 'black',
        [onHover] : { color : props?.colorHover ?? FACEBOOK_BLUE }
    }

    const ButtonLocal = ({ children } : any ) => {
        return (
            <div onClick={props.onClick} {...css(color)}>
                
                <div style={{ display : 'inline' }}>{children}</div>
               
                    {(props.items as any)?.length > 0 && 
                        <div style={{ display : 'inline', position : 'absolute', marginLeft : 3 }}>
                            <ChevronDown size={20}/>
                        </div>
                    }
             
                
            </div>
        )
    }

    const ButtonIILocal = ({ children } : any ) => {
        return (
            <div {...css({ ...getFontPoppins(), marginLeft : 30, fontWeight : 400, transition : "300ms", [onHover] : { color : FACEBOOK_BLUE }})}>
                {children}
            </div>
        )
    }

    const LinkInline = ({ children, href, onClick } : any ) => {
        return (
            <a onClick={onClick} {...css({ textDecoration : 'none', [':link'] : { color : 'black', textDecoration : 'none' },[":visited"] : { color : 'black'}})} href={href ? href : '#'}>
                {children}
            </a>
        )
    }

    const [hover, setHover ] = useState(false)
    return (<>
        <div style={{ cursor : 'pointer'}} onMouseEnter={()=>setHover(true)} onMouseLeave={()=>setHover(false)}>
            <X>
                
                    {
                        props.href  ? 
                            
                                    <LinkInline href={props.href}>
                                        <ButtonLocal>
                                            {props.children}
                                        </ButtonLocal>
                                    </LinkInline> 
                                    : 
                                    <ButtonLocal>
                                        {props.children}
                                    </ButtonLocal>
                    }
                    
                
            </X>
            <div style={{ paddingTop : 10, marginLeft : -20 }}>
            { props.items && 
                <>
                    { hover && 
                        <div style={{ position : 'absolute', width : 300, height : props.items ? props.items.length * menuItemHeight : 0, backgroundColor : 'white', borderRadius : 10}}>
                            { props.items && 
                                <>
                                    {props.items.map(( item : any )=>{
                                        return <div {...css({
                                            height : menuItemHeight,
                                            paddingLeft : 10, 
                                            width : 'calc(100% - 10px)',
                                            borderRadius : 10,
                                            transition : '300ms',
                                            [onHover] : {
                                                backgroundColor : `rgba(${FACEBOOK_BLUE_ARR.join(",")},0.1)`
                                            }
                                            
                                        })}>
                                            <X align="left">
                                                <GridRow height={menuItemHeight}>
                                                    <LinkInline onClick={item?.onClick} href={item?.href}>
                                                    
                                                        <ButtonIILocal>
                                                            {item.value}
                                                        </ButtonIILocal>
                                                    
                                                    </LinkInline>
                                                </GridRow>
                                             </X>
                                        </div>
                                    })}
                            
                                </>
                            }
                        </div>
                    }
                </>
            }
            </div>
        </div>
    </>)
}




const MenuItemHoverMobile = ( props : { children ?: any, href ?: string, items ?: { value : string, href ?: string }[] }) => {

    const [ isOpen, setIsOpen ] = useState( false )

    const menuItemHeight : number = 50
    const ButtonLocal = ({ children } : any ) => {
        return (
            <div {...css({ ...getFontPoppins(), fontWeight : 600, transition : "300ms", [onHover] : { color : FACEBOOK_BLUE }})}>
                {children}
            </div>
        )
    }

    const ButtonIILocal = ({ children } : any ) => {
        return (
            <div {...css({ ...getFontPoppins(), marginLeft : 30, fontWeight : 400, transition : "300ms", [onHover] : { color : FACEBOOK_BLUE }})}>
                {children}
            </div>
        )
    }

    const LinkInline = ({ children, href } : any ) => {
        return (
            <a {...css({ textDecoration : 'none', [':link'] : { color : 'black', textDecoration : 'none' },[":visited"] : { color : 'black'}})} href={href ? href : '#'}>
                {children}
            </a>
        )
    }

    return (<>
        <div style={{ cursor : 'pointer', width : '100%', backgroundColor : ''}} onClick={()=>setIsOpen(!isOpen)}>
            <X>

                <GridRow height={menuItemHeight}>
                    <div style={{ marginTop : 8 }}>
                        {
                            props.href  ? 
                                
                                <LinkInline href={props.href}>
                                    <ButtonLocal>
                                        {props.children}
                                    </ButtonLocal>
                                </LinkInline> 
                                        : 
                                        <ButtonLocal>
                                            {props.children}
                                </ButtonLocal>
                        }
                    </div>
                </GridRow>
                    
                
            </X>
            <div style={{ paddingTop : 10, marginLeft : -20 }}>
            { props.items && 
                <>
                    { isOpen && 
                        <div style={{ width : '100%', height : props.items ? props.items.length * menuItemHeight : 0, backgroundColor : 'white', borderRadius : 10}}>
                            { props.items && 
                                <>
                                    {props.items.map(( item : any )=>{
                                        return <div {...css({
                                            height : menuItemHeight,
                                            paddingLeft : 10, 
                                            width : 'calc(100% - 10px)',
                                            borderRadius : 10,
                                            transition : '300ms',
                                            [onHover] : {
                                                backgroundColor : `rgba(${FACEBOOK_BLUE_ARR.join(",")},0.1)`
                                            }
                                            
                                        })}>
                                            <X align="center">
                                                <GridRow height={menuItemHeight}>
                                                    <LinkInline href={item?.href}>
                                                    
                                                        <ButtonIILocal>
                                                            {item.value}
                                                        </ButtonIILocal>
                                                    
                                                    </LinkInline>
                                                </GridRow>
                                             </X>
                                        </div>
                                    })}
                            
                                </>
                            }
                        </div>
                    }
                </>
            }
            </div>
        </div>
    </>)
}


