import { css } from "glamor"
import React from "react"
import { on } from "./Hide"

const VERSION : string = '1.0.2'

export default ( props : { 
    p ?: number | string, 
    l ?: number | string,
    r ?: number | string,
    t ?: number | string,
    b ?: number | string,
    children ?: any, 
    style ?: any,
    breakpoint ?: {
        value : number, 
        p ?: number | string, 
        l ?: number | string,
        r ?: number | string,
        t ?: number | string,
        b ?: number | string,
        style ?: any  
    } 
}) => {

    return <div {...css({ 
        padding: props.p !== undefined ? props.p : 20, 
        ...( props.l !== undefined  ? { paddingLeft: props.l    } : {}),
        ...( props.r !== undefined  ? { paddingRight: props.r   } : {}),
        ...( props.b !== undefined  ? { paddingBottom: props.b  } : {}),
        ...( props.t !== undefined  ? { paddingTop: props.t     } : {}),
        ...props.style,
        ...( props?.breakpoint?.value ? {
            [ on( props.breakpoint.value ) ]:{
                padding: props?.breakpoint?.p ?? props.p ?? 20, 
                paddingLeft: props?.breakpoint?.l ?? props.l ?? undefined, 
                paddingRight: props?.breakpoint?.r ?? props.r ?? undefined, 
                paddingBottom: props?.breakpoint?.b ?? props.b ?? undefined, 
                paddingTop: props?.breakpoint?.t ?? props.t ?? undefined, 
                ...props?.breakpoint?.style,
            }
        } : {})
         
    })}>
            {props.children}
    </div>
}