export const CircleBorderV2 = ({ children, gradient, backgroundColor, size, lineWidth } : any ) => {
    lineWidth = lineWidth ? lineWidth : 5
    size = size ? size : 35
    return(
        <div style={{ marginTop : -5, marginLeft : 8, width : size, height : size, ...gradient, borderRadius : '100%', marginBottom : 5 }}>
         
                <div style={{ marginLeft : lineWidth/2, transform : `translate(0,${lineWidth/2}px)`,  width : size - lineWidth , height : size - lineWidth, backgroundColor,  borderRadius : '100%' }}>
            
                    <XY>
                        { children }
                    </XY>
                </div>
          
        </div>
    )
}

export const SquareBorderV2 = ({ children, gradient, backgroundColor, size, lineWidth, borderRadiusOuter, borderRadiusInner } : any ) => {
    lineWidth = lineWidth ? lineWidth : 5
    size = size ? size : 35
    return(
        <div style={{ marginTop : -5, marginLeft : 8, width : size, height : size, ...gradient, borderRadius : borderRadiusOuter, marginBottom : 5 }}>
         
                <div style={{ marginLeft : lineWidth/2, transform : `translate(0,${lineWidth/2}px)`,  width : size - lineWidth , height : size - lineWidth, backgroundColor,  borderRadius : borderRadiusInner }}>
            
                    <XY>
                        { children }
                    </XY>
                </div>
          
        </div>
    )
}

